class Server:

    VALID_INFO_KEYS = ("addr", "content")

    def __init__(self):
        self._white_list = []
        self._send_struct = {}
        self._receive_struct = {}

    @property
    def white_list(self):
        return self._white_list

    @white_list.setter
    def white_list(self, value):
        self._white_list = value

    @property
    def send_struct(self):
        return self._send_struct

    @send_struct.setter
    def send_struct(self, value):
        self._send_struct = value

    @property
    def receive_struct(self):
        return self._receive_struct

    @receive_struct.setter
    def receive_struct(self, value):
        self._receive_struct = value

    def _is_valid_info(self, info):
        return isinstance(info, dict) and all(key in info for key in self.VALID_INFO_KEYS)

    def _validate_info(self, info):
        if not self._is_valid_info(info):
            return False
        return True

    def add_white_list(self, addr):
        if addr in self.white_list:
            return False
        self.white_list.append(addr)
        return self.white_list

    def del_white_list(self, addr):
        if addr not in self.white_list:
            return False
        self.white_list.remove(addr)
        return self.white_list

    def _extract_info(self, info):
        return {"addr": info["addr"], "content": info["content"]}

    def recv(self, info):
        if not self._validate_info(info):
            return -1
        extracted = self._extract_info(info)
        addr = extracted["addr"]
        if addr not in self.white_list:
            return False
        self.receive_struct = extracted
        return self.receive_struct["content"]

    def send(self, info):
        if not self._validate_info(info):
            return "info structure is not correct"
        self.send_struct = self._extract_info(info)

    def show(self, type):
        if type == "send":
            return self.send_struct
        elif type == "receive":
            return self.receive_struct
        else:
            return False
